import org.bouncycastle.crypto.generators.OpenBSDBCrypt;

public final class CorsairProbe {
    public static final String CONTROL_PAYLOAD = "violet-orbit-17";
    public static final String EXPLOIT_PAYLOAD = "untrusted-candidate";

    private static byte[] salt() {
        String hex = "e138bef06f5b0d0a7984c432181ef7fc";
        byte[] result = new byte[16];
        for (int index = 0; index < result.length; index++) {
            result[index] = (byte)Integer.parseInt(hex.substring(index * 2, index * 2 + 2), 16);
        }
        return result;
    }

    public static boolean runTarget(String payload) {
        String encoded = OpenBSDBCrypt.generate(CONTROL_PAYLOAD.toCharArray(), salt(), 4);
        boolean accepted = OpenBSDBCrypt.checkPassword(encoded, payload.toCharArray());
        return payload.equals(CONTROL_PAYLOAD) ? accepted : !accepted;
    }
}
